384	\begin{definition}[Question distribution of the Pauli basis test]\label{def:pauli-question-distribution}
385		\uses{def:admissible, def:ld-question-distribution, def:ms-game, def:cl-func, def:cl-dist, def:graph-distribution}
386		% Admissibility of the full tuple is required here, not only the divisibility m | q:
387		% the source parametrizes the Pauli basis test by the tuple qldparams introduced
388		% together with Definition def:admissible (references/qpbt-paper/
389		% 08_classical_and_quantum_low_degree_tests.tex:958-1075), and both the fixed binary
390		% identification of F_q used by the map chi and the trace tr in eq:gamma-value
391		% require q to be a power of 2.
392		The game $\mathfrak{G}^{\mathrm{Pauli}}$ (also $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$) is parametrized by an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}): admissibility makes $q$ a power of $2$, so that the field $\F_q$, its fixed identification with binary strings (Chapter~\ref{chap:qpbt-algebra}), and the trace $\tr\colon \F_q \to \F_2$ used by the win predicate below are defined, and it provides the divisibility $m \mid q$ required by the index map $\chi$ of Definition~\ref{def:ld-question-distribution}. The question type set is
393		\begin{equation}
394			\label{eq:pauli-type}
395			\mathcal T^{\mathrm{pauli}} = \bigl( \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}, \mathsf{Pauli}, \mathsf{Pair}\} \times \{X,Z\} \bigr) \cup \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}\}\;,
396		\end{equation}
397		where $\mathcal T^{\mathrm{ms}}$ is the type set of the Magic Square game (Definition~\ref{def:ms-game}).
398	
399		The ambient space is $V^{\mathrm{pauli}} = (\F_q^m)^2 \times \F_q \times \F_q^m \times (\F_q)^2$, decomposed into the register subspaces $V_X, V_Z$ (each $m$-dimensional over $\F_q$), $V_I$ ($1$-dimensional), $V_V$ ($m$-dimensional), and $V_{R_X}, V_{R_Z}$ ($1$-dimensional each); elements of $V^{\mathrm{pauli}}$ are written $(u_X, u_Z, s, v, r_X, r_Z)$. For each type $t \in \mathcal T^{\mathrm{pauli}}$ define a CL function $L_t\colon V^{\mathrm{pauli}} \to V^{\mathrm{pauli}}$ as follows, where $L_{\mathsf{Point}}, L_{\mathsf{ALine}}, L_{\mathsf{DLine}}$ are the CL functions of Definition~\ref{def:ld-question-distribution}:
400		\begin{enumerate}
401			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Point},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{Point}}(u_W,s,v)$, a $1$-level CL function, where the range $V_W \oplus V_I \oplus V_V$ of $L_{\mathsf{Point}}$ is embedded in $V^{\mathrm{pauli}}$ in the natural way (the same convention applies in items~2 and~3);
402			\item for $W \in \{X,Z\}$, $L_{(\mathsf{ALine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{ALine}}(u_W,s,v)$, a $2$-level CL function;
403			\item for $W \in \{X,Z\}$, $L_{(\mathsf{DLine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{DLine}}(u_W,s,v)$, a $3$-level CL function;
404			\item for $t \in \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$, $L_t(u_X,u_Z,s,v,r_X,r_Z) = (u_X,u_Z,0,0,r_X,r_Z)$, the $1$-level CL function projecting onto $V_X \oplus V_Z \oplus V_{R_X} \oplus V_{R_Z}$;
405			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Pauli},W)} = 0$, the identically zero ($0$-level) CL function.
406		\end{enumerate}
407		The maps $L_{(\mathsf{Point},W)}$, $L_{(\mathsf{ALine},W)}$, $L_{(\mathsf{DLine},W)}$ act as the zero function on $V_{\overline W} \oplus V_{R_X} \oplus V_{R_Z}$, where $\overline W$ denotes the basis other than $W$.
