412			&(\mathsf{ALine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{DLine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pauli},Z)\;,\\
413			&(\mathsf{Point},X) \,\text{---}\, \mathsf{Variable}_1\;, &&(\mathsf{Point},Z) \,\text{---}\, \mathsf{Variable}_5\;, &&\\
414			&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pair},X)\;, &&(\mathsf{Pair},X) \,\text{---}\, \mathsf{Pair}\;, &&\\
415			&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pair},Z)\;, &&(\mathsf{Pair},Z) \,\text{---}\, \mathsf{Pair}\;; &&
